def copy_talks_forward(apps, schema_editor):
    ProgrammeTalk = apps.get_model('events', 'ProgrammeTalk')
    ProgrammeItem = apps.get_model('events', 'ProgrammeItem')
    ProgrammeItem.objects.bulk_create([
        ProgrammeItem(
            programme_id=pt.programme_id,
            talk_id=pt.talk_id,
            position=pt.position,
        )
        for pt in ProgrammeTalk.objects.all()
    ])


def copy_talks_backward(apps, schema_editor):
    # Breaks have no ProgrammeTalk equivalent, so only talk items are kept.
    ProgrammeTalk = apps.get_model('events', 'ProgrammeTalk')
    ProgrammeItem = apps.get_model('events', 'ProgrammeItem')
    ProgrammeTalk.objects.bulk_create([
        ProgrammeTalk(
            programme_id=item.programme_id,
            talk_id=item.talk_id,
            position=item.position,
        )
        for item in ProgrammeItem.objects.filter(talk__isnull=False)
    ])


